"""General functions for the 'Service Functions' page. These functions are called from the top
level IntegrityService interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.integrity_objects as IntegrityObjects
import interops.libraries.integrity.pages.service_screen as ServicePgObj
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME
import squishtest3 as sq
import test
import logging


logger = logging.getLogger(__name__)

@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_funcs_open_select_machine_state_menu() -> bool:
    '''
    Open the Select Machine State menu from the Service Functions menu

    Returns:
        bool - True if the Select Machine State menu is open
    '''
    logger.info("open_select_machine_state_menu called.")
    try:
        service_menu = ServicePgObj.ServiceMenuBar()
        if service_menu.ready():
            service_menu.service_functions()

            service_funcs_menu = ServicePgObj.ServiceFunctionsMenuBar()
            for n in range(2):
                try:
                    service_funcs_menu.select_machine_state()
                    sq.waitForObjectExists(IntegrityObjects.States_Group, 30000)
                    return True
                except Exception:
                    logger.exception("open_select_machine_state_menu failed to open attempt " + str(n))
        return False
    except Exception as e:
        logger.exception("open_select_machine_state_menu failed to open", str(e))
        return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_funcs_open_service_page(page: str) -> None:
    '''
    Opens the Service Pages in the Service Functions menu
    '''

    # TODO: this requires Extra Windows="Service Core Applets Server" in winwrapper.ini
    service_menu = ServicePgObj.ServiceMenuBar()
    service_menu.service_functions()

    service_funcs_menu = ServicePgObj.ServiceFunctionsMenuBar()
    service_funcs_menu.service_pages()

    service_pages_menu = ServicePgObj.ServicePages()
    sq.nativeType("<PageDown>")
    for i in range(3):
        if not service_pages_menu.select_page(page):
            sq.nativeType("<PageUp>")
            continue
        break